    const EncounterTable* getEncounterTable(Enums::GameVersion versionOrGroup) {
        switch (versionOrGroup) {
            case Enums::GameVersion::FRLG:
            case Enums::GameVersion::FR:
            case Enums::GameVersion::LG:
                return &TABLE_FRLG;
            case Enums::GameVersion::RSE:
            case Enums::GameVersion::RU:
            case Enums::GameVersion::SA:
            case Enums::GameVersion::EM:
                return &TABLE_RSE;
            default:
                return nullptr;
        }
    }

    uint8_t encounterVersionBit(Enums::GameVersion version) {
        switch (version) {
            case Enums::GameVersion::FR: return 1;
            case Enums::GameVersion::LG: return 2;
            case Enums::GameVersion::RU: return 1;
            case Enums::GameVersion::SA: return 2;
            case Enums::GameVersion::EM: return 4;
            default: return 0;
        }
    }

